import random
# 게임 평가를 몬테카를로로: 에이전트는 늘 A, 상대는 1/2 씩 무작위
LEAVES = {"A": {1: -50, 2: 50}, "B": {1: 1, 2: 3}, "C": {1: -5, 2: 15}}
pi_agent = lambda s: {"A": 1.0}
pi_opp = lambda s: {1: 0.5, 2: 0.5}

def sample(dist):
    acts, probs = zip(*dist.items())
    return random.choices(acts, weights=probs)[0]

def simulate():
    b = sample(pi_agent("root"))          # 에이전트 차례
    k = sample(pi_opp(b))                 # 상대 차례
    return LEAVES[b][k]                   # 끝 상태의 효용

random.seed(1)
for n in (20, 1000, 100000):
    us = [simulate() for _ in range(n)]
    print(n, "판 평균:", sum(us) / n)

from functools import lru_cache
# 반감 게임: (n, 차례). 행동 dec: n-1, half: n//2. n=0 일 때 차례인 쪽이 이긴다.
@lru_cache(None)
def minimax(n, player):
    if n == 0:
        return (1 if player == "agent" else -1), None
    nxt = "opp" if player == "agent" else "agent"
    vals = {a: minimax(m, nxt)[0] for a, m in (("decrement", n - 1), ("half", n // 2))}
    pick = max if player == "agent" else min
    act = pick(vals, key=vals.get)           # 동점이면 앞의 decrement
    return vals[act], act

for n in range(1, 12):
    print(n, minimax(n, "agent"))

# 네 정책을 서로 붙여 본다 (게임 1). 정책 = 자식 값 dict -> 값.
LEAVES = {"A": {1: -50, 2: 50}, "B": {1: 1, 2: 3}, "C": {1: -5, 2: 15}}
pi_min = lambda d: min(d.values())                 # 최악의 상대
pi_7   = lambda d: sum(d.values()) / len(d)        # 반반 무작위 상대
def agent(opp_model):                              # opp_model 을 가정하고 고른 통
    return max(LEAVES, key=lambda b: opp_model(LEAVES[b]))
pi_max, pi_exp = agent(pi_min), agent(pi_7)        # 'B', 'C'
for name, bin_ in (("pi_max", pi_max), ("pi_exptmax(7)", pi_exp)):
    row = [opp(LEAVES[bin_]) for opp in (pi_min, pi_7)]
    print(f"{name:14s} 통={bin_}  vs pi_min={row[0]:>5}  vs pi_7={row[1]:>5}")

# 게임 2: 고른 통에서 동전 앞면이면 왼쪽 통(감아 돌기)으로, 뒷면이면 그대로. 그다음 상대가 min.
BINS = {"A": [-50, 50], "B": [1, 3], "C": [-5, 15]}
LEFT = {"A": "C", "B": "A", "C": "B"}
def coin_value(b):
    heads, tails = min(BINS[LEFT[b]]), min(BINS[b])   # 상대 = min 노드
    return 0.5 * heads + 0.5 * tails                 # 동전 = 기댓값 노드
vals = {b: coin_value(b) for b in BINS}
print(vals, "->", max(vals, key=vals.get), max(vals.values()))

# 이동 순서가 가지치기를 바꾼다: 같은 트리, 자식 순서만 다르게
import math
def ab(node, is_max, a=-math.inf, b=math.inf, seen=None):
    if not isinstance(node, list):
        seen.append(node); return node
    v = -math.inf if is_max else math.inf
    for ch in node:
        c = ab(ch, not is_max, a, b, seen)
        if is_max: v = max(v, c); a = max(a, v)
        else:      v = min(v, c); b = min(b, v)
        if a >= b: break
    return v
for tree in ([[3, 5], [2, 10]], [[2, 10], [3, 5]]):
    seen = []
    print(tree, "값", ab(tree, True, seen=seen), "본 잎", seen)

# 깊이 제한 minimax: 반감 게임, 깊이 d 가 0 이 되면 Eval 로 끊는다.
def eval_fn(n, player):
    return 0.0                      # '모르겠다' — 가장 순진한 평가 함수
def V(n, player, d):
    if n == 0:
        return 1 if player == "agent" else -1
    if d == 0:
        return eval_fn(n, player)
    if player == "agent":           # 에이전트 차례에는 d 를 그대로
        return max(V(m, "opp", d) for m in (n - 1, n // 2))
    return min(V(m, "agent", d - 1) for m in (n - 1, n // 2))  # 상대가 두면 한 수 끝
for d in range(1, 6):
    print(f"d={d}:", [V(n, "agent", d) for n in range(1, 12)])
